args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?song ?p ?o WHERE {
  VALUES ?song { dbr:Sea_of_Voices dbr:Soft-Hearted_Hana }
  ?song ?p ?o .
  FILTER (?p IN (dbo:releaseDate, dbp:released))
}
ORDER BY ?song ?p

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?song ?songLabel ?date WHERE {
  VALUES ?song { dbr:Sea_of_Voices dbr:Soft-Hearted_Hana }
  OPTIONAL { ?song dbo:releaseDate ?rd . }
  OPTIONAL { ?song dbp:released ?rr . }
  BIND (COALESCE(?rd, ?rr) AS ?date)
  OPTIONAL { ?song rdfs:label ?songLabel . FILTER (lang(?songLabel) = 'en') }
}
ORDER BY ?date
LIMIT 1

